/**
 * Contract code generator (DECISIONS.md D-003).
 *
 *   Rust types (crates/ipc) ──contracts-gen──► JSON Schema ──this script──► Zod (TS) + Codable (Swift)
 *
 * Usage:
 *   tsx scripts/validation/gen-contracts.ts          # regenerate files
 *   tsx scripts/validation/gen-contracts.ts --check  # fail if generated files are stale
 *
 * Supports exactly the schema subset `schemars` emits for our types: objects, string enums,
 * adjacently-tagged unions (`#[serde(tag, content)]`), arrays, maps, nullable values,
 * primitives and `$ref`s. Anything else is a hard error so drift is never silent.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

type Schema = boolean | { [k: string]: unknown };
type Obj = Record<string, unknown>;

interface ContractDoc {
  protocolVersion: number;
  error: Obj;
  methods: { name: string; target: "core" | "host"; params: Obj; result: Obj }[];
  events: { name: string; payload: Obj }[];
  definitions: Record<string, Obj>;
}

const root = join(dirname(fileURLToPath(import.meta.url)), "../..");
const OUT_SCHEMA = join(root, "packages/contracts/schema/wisp.schema.json");
const OUT_TS = join(root, "packages/contracts/src/generated/contracts.ts");
const OUT_SWIFT = join(root, "apps/macos/Sources/IPC/Generated/Contracts.swift");
const HEADER = "Generated by scripts/validation/gen-contracts.ts from crates/ipc. Do not edit.";

const check = process.argv.includes("--check");

function fail(msg: string): never {
  console.error(`gen-contracts: ${msg}`);
  process.exit(1);
}

const raw = execFileSync("cargo", ["run", "-q", "-p", "wisp-ipc", "--bin", "contracts-gen"], {
  cwd: root,
  encoding: "utf8",
  stdio: ["ignore", "pipe", "inherit"],
});
const doc = JSON.parse(raw) as ContractDoc;

// ─── helpers ───────────────────────────────────────────────────────────────

const refName = (s: Obj): string | undefined =>
  typeof s.$ref === "string" ? s.$ref.replace("#/definitions/", "") : undefined;

function typesOf(s: Obj): string[] {
  const t = s.type;
  if (t === undefined) return [];
  return Array.isArray(t) ? (t as string[]) : [t as string];
}

/** Unwrap `X | null` forms. Returns the non-null schema and whether null was allowed. */
function unwrapNullable(s: Obj): { inner: Obj; nullable: boolean } {
  const any = (s.anyOf ?? s.oneOf) as Obj[] | undefined;
  if (any && any.length === 2 && any.some((x) => typesOf(x).join() === "null")) {
    return { inner: any.find((x) => typesOf(x).join() !== "null") as Obj, nullable: true };
  }
  const ts = typesOf(s);
  if (ts.length === 2 && ts.includes("null")) {
    return { inner: { ...s, type: ts.find((t) => t !== "null") }, nullable: true };
  }
  return { inner: s, nullable: false };
}

/** String enums appear either as `enum: [...]` or, when variants carry docs, as `oneOf` of consts. */
function stringEnum(s: Obj): string[] | undefined {
  if (Array.isArray(s.enum)) return s.enum as string[];
  // schemars groups undocumented variants into one `enum` arm and documented ones into `const` arms.
  const variants = s.oneOf as Obj[] | undefined;
  if (!variants?.length || variants.some((v) => v.properties !== undefined)) return undefined;
  const out: string[] = [];
  for (const v of variants) {
    if (typeof v.const === "string") out.push(v.const);
    else if (Array.isArray(v.enum) && v.enum.every((x) => typeof x === "string"))
      out.push(...(v.enum as string[]));
    else return undefined;
  }
  return out;
}

interface TaggedUnion {
  tag: string;
  content?: string;
  variants: { name: string; payload?: Obj }[];
}

function asTaggedUnion(s: Obj): TaggedUnion | undefined {
  const variants = s.oneOf as Obj[] | undefined;
  if (!variants) return undefined;
  let tag: string | undefined;
  let content: string | undefined;
  const out: TaggedUnion["variants"] = [];
  for (const v of variants) {
    const props = (v.properties ?? {}) as Record<string, Obj>;
    const constKey = Object.keys(props).find((k) => props[k]?.const !== undefined);
    if (!constKey) return undefined;
    if (tag && tag !== constKey) fail(`inconsistent union tag ${tag} vs ${constKey}`);
    tag = constKey;
    const others = Object.keys(props).filter((k) => k !== constKey);
    if (others.length > 1) fail(`internally-tagged unions are not supported yet (tag ${constKey})`);
    if (others.length === 1) {
      if (content && content !== others[0]) fail("inconsistent union content key");
      content = others[0];
    }
    out.push({
      name: String(props[constKey]!.const),
      payload: others.length ? props[others[0]!] : undefined,
    });
  }
  return { tag: tag!, content, variants: out };
}

/** Definitions in dependency order (referenced types first). */
function orderedDefinitions(): string[] {
  const deps = (s: unknown, acc: Set<string>) => {
    if (s && typeof s === "object") {
      const r = refName(s as Obj);
      if (r) acc.add(r);
      for (const v of Object.values(s as Obj)) deps(v, acc);
    }
    return acc;
  };
  const order: string[] = [];
  const state = new Map<string, "visiting" | "done">();
  const visit = (name: string) => {
    if (state.get(name) === "done") return;
    if (state.get(name) === "visiting") fail(`recursive type ${name} is not supported`);
    state.set(name, "visiting");
    for (const d of deps(doc.definitions[name], new Set())) visit(d);
    state.set(name, "done");
    order.push(name);
  };
  for (const n of Object.keys(doc.definitions).sort()) visit(n);
  return order;
}

const camel = (s: string) => s.replace(/[._-](\w)/g, (_, c: string) => c.toUpperCase());

// ─── TypeScript / Zod ──────────────────────────────────────────────────────

function zod(s: Schema): string {
  if (s === true || (typeof s === "object" && Object.keys(s).length === 0)) return "z.unknown()";
  if (s === false) fail("`false` schema not supported");
  const { inner, nullable } = unwrapNullable(s);
  const base = zodInner(inner);
  return nullable ? `${base}.nullable()` : base;
}

function zodInner(s: Obj): string {
  const r = refName(s);
  if (r) return r;
  if (s.const !== undefined) return `z.literal(${JSON.stringify(s.const)})`;
  const en = stringEnum(s);
  if (en) return `z.enum(${JSON.stringify(en)})`;
  const tagged = asTaggedUnion(s);
  if (tagged) {
    const arms = tagged.variants.map((v) => {
      const fields = [`${JSON.stringify(tagged.tag)}: z.literal(${JSON.stringify(v.name)})`];
      if (tagged.content && v.payload) fields.push(`${JSON.stringify(tagged.content)}: ${zod(v.payload)}`);
      return `z.strictObject({ ${fields.join(", ")} })`;
    });
    return `z.discriminatedUnion(${JSON.stringify(tagged.tag)}, [${arms.join(", ")}])`;
  }
  const [t] = typesOf(s);
  switch (t) {
    case "string":
      return "z.string()";
    case "boolean":
      return "z.boolean()";
    case "integer": {
      const min = typeof s.minimum === "number" && s.minimum >= 0 ? ".nonnegative()" : "";
      return `z.number().int()${min}`;
    }
    case "number":
      return "z.number()";
    case "array":
      return `z.array(${zod(s.items as Schema)})`;
    case "object": {
      if (s.properties === undefined && s.additionalProperties && s.additionalProperties !== false) {
        return `z.record(z.string(), ${zod(s.additionalProperties as Schema)})`;
      }
      const props = (s.properties ?? {}) as Record<string, Obj>;
      const required = new Set((s.required as string[] | undefined) ?? []);
      const fields = Object.keys(props).map((k) => {
        const p = props[k]!;
        let expr = zod(p);
        if (p.default !== undefined) {
          expr = `${expr}.default(${refName(p) ? `() => ${refName(p)}.parse(${JSON.stringify(p.default)})` : JSON.stringify(p.default)})`;
        } else if (!required.has(k)) {
          expr = `${expr}.optional()`;
        }
        return `  ${JSON.stringify(k)}: ${expr},`;
      });
      const ctor = s.additionalProperties === false ? "z.strictObject" : "z.object";
      return `${ctor}({\n${fields.join("\n")}\n})`;
    }
    default:
      return fail(`unsupported schema: ${JSON.stringify(s)}`);
  }
}

function genTs(): string {
  const out: string[] = [`// ${HEADER}`, `import { z } from "zod";`, ""];
  out.push(`export const PROTOCOL_VERSION = ${doc.protocolVersion} as const;`, "");
  for (const name of orderedDefinitions()) {
    const def = doc.definitions[name]!;
    if (typeof def.description === "string") out.push(`/** ${def.description.replace(/\*\//g, "*\\/")} */`);
    out.push(`export const ${name} = ${zod(def)};`);
    out.push(`export type ${name} = z.output<typeof ${name}>;`, "");
  }
  out.push("export const methods = {");
  for (const m of doc.methods) {
    out.push(
      `  ${JSON.stringify(m.name)}: { target: ${JSON.stringify(m.target)}, params: ${zod(m.params)}, result: ${zod(m.result)} },`,
    );
  }
  out.push("} as const;", "");
  out.push("export const events = {");
  for (const e of doc.events) out.push(`  ${JSON.stringify(e.name)}: ${zod(e.payload)},`);
  out.push("} as const;", "");
  out.push(
    "export type MethodName = keyof typeof methods;",
    "export type EventName = keyof typeof events;",
    'export type MethodParams<M extends MethodName> = z.input<(typeof methods)[M]["params"]>;',
    'export type MethodResult<M extends MethodName> = z.output<(typeof methods)[M]["result"]>;',
    "export type EventPayload<E extends EventName> = z.output<(typeof events)[E]>;",
    "",
  );
  return out.join("\n");
}

// ─── Swift / Codable ───────────────────────────────────────────────────────

const SWIFT_KEYWORDS = new Set([
  "default",
  "class",
  "struct",
  "enum",
  "protocol",
  "case",
  "self",
  "Type",
  "internal",
  "public",
  "private",
  "static",
  "func",
  "var",
  "let",
  "in",
  "is",
  "as",
  "where",
  "switch",
  "return",
  "import",
  "true",
  "false",
  "nil",
]);
const swiftIdent = (s: string) => (SWIFT_KEYWORDS.has(s) ? `\`${s}\`` : s);

function swiftType(s: Schema): string {
  if (s === true || (typeof s === "object" && Object.keys(s).length === 0)) return "JSONValue";
  if (s === false) fail("`false` schema not supported");
  const { inner, nullable } = unwrapNullable(s);
  const base = swiftInner(inner);
  return nullable ? `${base}?` : base;
}

function swiftInner(s: Obj): string {
  const r = refName(s);
  if (r) return r;
  const [t] = typesOf(s);
  switch (t) {
    case "string":
      return "String";
    case "boolean":
      return "Bool";
    case "integer":
      return s.format === "int64"
        ? "Int64"
        : s.format === "uint32"
          ? "UInt32"
          : s.format === "uint64"
            ? "UInt64"
            : "Int";
    case "number":
      return "Double";
    case "array":
      return `[${swiftType(s.items as Schema)}]`;
    case "object":
      if (s.properties === undefined && s.additionalProperties && s.additionalProperties !== false) {
        return `[String: ${swiftType(s.additionalProperties as Schema)}]`;
      }
      return fail(`inline object types must be named definitions in Swift: ${JSON.stringify(s)}`);
    default:
      return fail(`unsupported Swift schema: ${JSON.stringify(s)}`);
  }
}

function swiftDef(name: string, def: Obj): string {
  const doc_ =
    typeof def.description === "string"
      ? def.description
          .split("\n")
          .map((l) => `/// ${l}`.trimEnd())
          .join("\n") + "\n"
      : "";
  const en = stringEnum(def);
  if (en) {
    const cases = en.map((v) => `    case ${swiftIdent(camel(v))} = ${JSON.stringify(v)}`);
    return `${doc_}public enum ${name}: String, Codable, Sendable, Equatable, CaseIterable {\n${cases.join("\n")}\n}`;
  }
  const tagged = asTaggedUnion(def);
  if (tagged) {
    const cases = tagged.variants.map((v) =>
      v.payload
        ? `    case ${swiftIdent(camel(v.name))}(${swiftType(v.payload)})`
        : `    case ${swiftIdent(camel(v.name))}`,
    );
    const decodeArms = tagged.variants.map((v) =>
      v.payload
        ? `        case ${JSON.stringify(v.name)}: self = .${camel(v.name)}(try c.decode(${swiftType(v.payload)}.self, forKey: .content))`
        : `        case ${JSON.stringify(v.name)}: self = .${camel(v.name)}`,
    );
    const encodeArms = tagged.variants.map((v) =>
      v.payload
        ? `        case .${camel(v.name)}(let v):\n            try c.encode(${JSON.stringify(v.name)}, forKey: .tag)\n            try c.encode(v, forKey: .content)`
        : `        case .${camel(v.name)}:\n            try c.encode(${JSON.stringify(v.name)}, forKey: .tag)`,
    );
    return `${doc_}public enum ${name}: Codable, Sendable, Equatable {
${cases.join("\n")}

    private enum CodingKeys: String, CodingKey {
        case tag = ${JSON.stringify(tagged.tag)}${tagged.content ? `\n        case content = ${JSON.stringify(tagged.content)}` : ""}
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .tag)
        switch tag {
${decodeArms.join("\n")}
        default:
            throw DecodingError.dataCorruptedError(forKey: .tag, in: c, debugDescription: "unknown ${name} variant \\(tag)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
${encodeArms.join("\n")}
        }
    }
}`;
  }
  if (typesOf(def)[0] === "object") {
    const props = (def.properties ?? {}) as Record<string, Obj>;
    const required = new Set((def.required as string[] | undefined) ?? []);
    const fields = Object.keys(props).map((k) => {
      const p = props[k]!;
      let t = swiftType(p);
      if (!required.has(k) && p.default === undefined && !t.endsWith("?")) t += "?";
      return { name: k, type: t };
    });
    const decls = fields.map((f) => `    public var ${swiftIdent(f.name)}: ${f.type}`);
    const params = fields.map((f) => `${f.name}: ${f.type}${f.type.endsWith("?") ? " = nil" : ""}`);
    const assigns = fields.map((f) => `        self.${f.name} = ${f.name}`);
    return `${doc_}public struct ${name}: Codable, Sendable, Equatable {
${decls.join("\n")}

    public init(${params.join(", ")}) {
${assigns.join("\n")}
    }
}`;
  }
  return fail(`unsupported Swift definition ${name}`);
}

function genSwift(): string {
  const out: string[] = [`// ${HEADER}`, "// swiftlint:disable all", "import Foundation", ""];
  out.push(`public let ipcProtocolVersion: UInt32 = ${doc.protocolVersion}`, "");
  for (const name of orderedDefinitions()) out.push(swiftDef(name, doc.definitions[name]!), "");
  out.push("public enum IPCMethods {");
  for (const m of doc.methods) {
    out.push(
      `    public static let ${camel(m.name)} = IPCMethod<${swiftType(m.params)}, ${swiftType(m.result)}>(name: ${JSON.stringify(m.name)}, target: .${m.target})`,
    );
  }
  out.push(
    "",
    "    /// Every known method and which side implements it. Used to route and reject unknown methods.",
  );
  out.push("    public static let targets: [String: IPCTarget] = [");
  for (const m of doc.methods) out.push(`        ${JSON.stringify(m.name)}: .${m.target},`);
  out.push("    ]");
  out.push("}", "", "public enum IPCEvents {");
  for (const e of doc.events) {
    out.push(
      `    public static let ${camel(e.name)} = IPCEvent<${swiftType(e.payload)}>(name: ${JSON.stringify(e.name)})`,
    );
  }
  out.push("}", "");
  return out.join("\n");
}

// ─── write / check ─────────────────────────────────────────────────────────

const outputs: [string, string][] = [
  [OUT_SCHEMA, JSON.stringify(doc, null, 2) + "\n"],
  [OUT_TS, genTs()],
  [OUT_SWIFT, genSwift()],
];

let stale = false;
for (const [path, content] of outputs) {
  let current = "";
  try {
    current = readFileSync(path, "utf8");
  } catch {
    /* missing → stale */
  }
  if (current === content) continue;
  if (check) {
    console.error(`stale: ${path.replace(root + "/", "")}`);
    stale = true;
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${path.replace(root + "/", "")}`);
  }
}
if (stale) fail("generated contracts are out of date — run `pnpm contracts`");
if (check) console.log("contracts up to date");
